SELECT * FROM app_dependency
WHERE app_id = #{appId} AND app_version = #{version}
ORDER BY dependency_type, dependency_code

SELECT * FROM app_dependency
AND (dependency_code LIKE CONCAT('%', #{keyword}, '%') OR dependency_name LIKE CONCAT('%', #{keyword}, '%') OR app_code LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY app_code, dependency_type, dependency_code LIMIT #{offset}, #{pageSize}

